const headers = $input.item.json.headers || {};
const auth = headers['authorization'] || headers['Authorization'] || '';
const token = auth.toLowerCase().startsWith('bearer ') ? auth.slice(7).trim() : '';
if (!token) return { json: { ok: false, status: 401, error: 'Missing session token' } };
return { json: { token: token } };

const rows = $input.item.json;
const row = Array.isArray(rows) ? (rows[0] || null) : (rows && (rows.user_id || rows.id) ? rows : null);
if (!row) return { json: { ok: false, status: 401, error: 'Invalid or expired session' } };
if (row.user_role !== 'admin') return { json: { ok: false, status: 403, error: 'Admin access required' } };
return { json: { ok: true } };

// Every upstream fetch uses fullResponse, so each arrives as ONE item shaped
// { body, statusCode, headers } instead of n8n splitting the array into many
// items. Reference them with .first() -- .item would depend on paired-item
// lineage, which HTTP nodes break.
function res(name){
  try { const j = $(name).first().json || {}; return { code: j.statusCode || 0, body: j.body }; }
  catch (e) { return { code: 0, body: null }; }
}
function arr(v){ return Array.isArray(v) ? v : []; }

const ch = res('Fetch Channels');
const pl = res('Fetch Platforms');
const sk = res('Fetch Stream Key');
const sv = res('Fetch Servers');

// Authorization problems are the common failure and deserve a clear message
// rather than an empty list that reads as "you have no channels".
if (ch.code === 401 || ch.code === 403 || sk.code === 401 || sk.code === 403) {
  return { json: { ok: false, status: 401,
    error: 'Restream authorization failed or expired. Re-authorize the "Restream OAuth2" credential in n8n (Credentials -> Restream OAuth2 -> Connect).' } };
}
if (ch.code && (ch.code < 200 || ch.code >= 300)) {
  return { json: { ok: false, status: 502, error: 'Restream API error on channels (HTTP ' + ch.code + ').' } };
}

// Restream platform names -> the keys the Go Live modal and bid page use.
const NAME_TO_KEY = {
  'tiktok': 'tiktok',
  'youtube': 'youtube',
  'youtube stream now': 'youtube',
  'facebook': 'facebook',
  'facebook pages': 'facebook',
  'instagram': 'instagram',
  'twitter': 'x',
  'x': 'x'
};

const idToName = {};
arr(pl.body).forEach(function(p){
  if (p && p.id != null) idToName[String(p.id)] = String(p.name || '');
});

const channels = [];
const watch_urls = {};
arr(ch.body).forEach(function(c){
  if (!c || c.id == null) return;
  const pname = idToName[String(c.streamingPlatformId)] || '';
  const key = NAME_TO_KEY[pname.toLowerCase()] || null;
  const url = String(c.url || '').trim();
  const active = c.active !== false;
  channels.push({
    platform_key: key,
    platform_name: pname || ('platform ' + c.streamingPlatformId),
    display_name: String(c.displayName || ''),
    url: url,
    embed_url: String(c.embedUrl || ''),
    active: active
  });
  // Only surface links we can place in a field and that are actually live.
  if (key && url && active) watch_urls[key] = url;
});

// Stream key + ingest server are both optional: if either is missing the
// operator just fills that field by hand, exactly as before.
const skBody = sk.body || {};
const stream_key = String(skBody.streamKey || skBody.stream_key || '');
const servers = arr(sv.body);
let ingest = '';
for (let i = 0; i < servers.length; i++) {
  if (String(servers[i].name || '').toLowerCase() === 'autodetect') { ingest = String(servers[i].rtmpUrl || ''); break; }
}
if (!ingest && servers.length) ingest = String(servers[0].rtmpUrl || '');

return { json: {
  ok: true,
  status: 200,
  count: channels.length,
  channels: channels,
  watch_urls: watch_urls,
  rtmp_ingest_url: ingest,
  stream_key: stream_key,
  platforms_loaded: arr(pl.body).length
} };
